import{_ as c,C as g,o as i,c as r,j as n,a as d,E as e,a2 as h}from"./chunks/framework.DBmpDOAE.js";const L=JSON.parse('{"title":"3. Rules & mechanics","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/rules.md","filePath":"gdd/rules.md"}'),a={name:"gdd/rules.md"},l={id:"_3-1-thanh-phan-tren-board",tabindex:"-1"},s={id:"_3-2-tap-va-di-chuyen",tabindex:"-1"},m={id:"_3-3-va-cham",tabindex:"-1"},u={id:"_3-3b-cam-giac-vat-ly-cua-bong",tabindex:"-1"},b={id:"_3-3b2-ban-jelly",tabindex:"-1"},p={id:"_3-3b3-ban-magic",tabindex:"-1"},v={id:"_3-3b4-theme-fluffy",tabindex:"-1"},y={id:"_3-3c-giao-dien-sang-toi",tabindex:"-1"},k={id:"_3-4-cap-bien-mat",tabindex:"-1"},_={id:"_3-5-thang-va-thua",tabindex:"-1"},F={id:"_3-6-hud-va-nut-theo-clip",tabindex:"-1"},T={id:"_3-7-bang-mau",tabindex:"-1"},x={id:"_3-8-level",tabindex:"-1"};function E(C,t,f,D,B,A){const o=g("Badge");return i(),r("div",null,[t[39]||(t[39]=n("h1",{id:"_3-rules-mechanics",tabindex:"-1"},[d("3. Rules & mechanics "),n("a",{class:"header-anchor",href:"#_3-rules-mechanics","aria-label":'Permalink to "3. Rules & mechanics"'},"​")],-1)),n("h2",l,[t[0]||(t[0]=d("3.1 Thành phần trên board ",-1)),e(o,{type:"tip",text:"Live"}),t[1]||(t[1]=d()),t[2]||(t[2]=n("a",{class:"header-anchor",href:"#_3-1-thanh-phan-tren-board","aria-label":'Permalink to "3.1 Thành phần trên board <Badge type="tip" text="Live" />"'},"​",-1))]),t[40]||(t[40]=h('<table tabindex="0"><thead><tr><th>Thành phần</th><th>Mô tả</th></tr></thead><tbody><tr><td><strong>Hạt</strong></td><td>Hình tròn, có màu. Mỗi hạt thuộc đúng một cặp.</td></tr><tr><td><strong>Cặp</strong></td><td>2 hạt cùng màu, nối nhau bằng một sợi dây cùng màu.</td></tr><tr><td><strong>Dây</strong></td><td>Đường nối 2 hạt của một cặp. Có thể thẳng hoặc cong/gấp khúc (theo clip). Dây của các cặp khác nhau có thể cắt chéo nhau.</td></tr><tr><td><strong>Kích thước hạt</strong></td><td>Trong một level, <strong>hầu hết hạt có cùng một cỡ</strong> (cỡ hạt thường của level, chọn theo kích cỡ hình). Ngoại lệ là <strong>bóng bự</strong>: hạt to hơn hẳn, đặt ở chi tiết tròn kín của hình (mắt, mũi, nút áo). 2 hạt trong cùng một cặp có thể khác kích thước (bóng bự nối với hạt thường, hoặc hai bóng bự thành một cặp).</td></tr></tbody></table>',1)),n("h2",s,[t[3]||(t[3]=d("3.2 Tap và di chuyển ",-1)),e(o,{type:"tip",text:"Live"}),t[4]||(t[4]=d()),t[5]||(t[5]=n("a",{class:"header-anchor",href:"#_3-2-tap-va-di-chuyen","aria-label":'Permalink to "3.2 Tap và di chuyển <Badge type="tip" text="Live" />"'},"​",-1))]),t[41]||(t[41]=h("<ul><li>Người chơi tap vào một hạt bất kỳ; hạt đó là <strong>hạt di chuyển</strong>, hạt còn lại của cặp là <strong>hạt đích</strong>.</li><li>Hạt di chuyển chạy <strong>dọc theo sợi dây</strong> về phía hạt đích; dây ngắn dần sau lưng nó.</li><li>Khi một hạt đang chạy, <strong>không tap được hạt còn lại của cặp đó</strong>.</li><li>Khi một hạt đang chạy, người chơi <strong>vẫn tap được hạt của các cặp khác</strong>; nhiều hạt có thể chạy cùng lúc.</li><li>Tốc độ di chuyển: chấm <strong>khởi đầu ở 500 px thế giới / giây</strong> và <strong>tăng đều lên 750 px/giây sau 1 giây</strong>, rồi giữ nguyên gia tốc đó (250 px/s²) cho tới hết quãng đường còn lại (<code>START_SPEED</code>, <code>MOVE_SPEED</code> trong <code>src/game/tuning.ts</code>). Khi bị chặn và quay về: <strong>1020 px/giây</strong> (= 1,36 × <code>MOVE_SPEED</code>). Chỉnh <code>MOVE_SPEED</code> bằng thanh cheat ⚙ speed trong game (bản Fluffy: ⚙ tuning); bấm Confirm khi chạy local để ghi vào code. Lấy theo cảm giác của clip tham khảo; chỉnh lại khi chơi thử.</li><li><strong>Zoom:</strong> người chơi chụm 2 ngón tay để thu nhỏ và kéo 2 ngón ra để phóng to board, tối đa 3 lần. Khi đang phóng to, người chơi kéo (pan) được board. Zoom chỉ áp dụng cho board, HUD giữ nguyên kích thước.</li></ul>",1)),n("h2",m,[t[6]||(t[6]=d("3.3 Va chạm ",-1)),e(o,{type:"tip",text:"Live"}),t[7]||(t[7]=d()),t[8]||(t[8]=n("a",{class:"header-anchor",href:"#_3-3-va-cham","aria-label":'Permalink to "3.3 Va chạm <Badge type="tip" text="Live" />"'},"​",-1))]),t[42]||(t[42]=h("<ul><li>Nếu trên đường đi, hạt di chuyển <strong>đụng hạt của một cặp khác</strong> → lượt đó bị hủy, hạt di chuyển quay về vị trí ban đầu, không có cặp nào biến mất, và người chơi <strong>mất 1 tim</strong>. Màn hình không rung; phản hồi va chạm là biến dạng đàn hồi của 2 hạt (3.3b).</li><li>Chỉ va chạm với <strong>hạt</strong> mới tính; dây của các cặp khác không chặn đường (dây cắt chéo nhau thoải mái).</li><li><strong>Hitbox:</strong> hai hạt va chạm khi khoảng cách tâm nhỏ hơn <strong>78%</strong> tổng hai bán kính (<code>HIT_SCALE</code> trong <code>src/core/solver.ts</code>; trước đây 85%). Với hạt thường (bán kính 16): hạt đứng yên có tâm cách dây <strong>dưới 25 px</strong> thì chặn hạt chạy trên dây; từ 25 px trở lên (mép hạt cách mép dây khoảng 6 px) thì hạt chạy đi qua. Hai hạt chỉ chạm mép (ví dụ hai hạt nằm sát nhau ở chỗ cắt) không tính là va chạm.</li><li><strong>Cặp có đường thông (sẽ chạm được nhau):</strong> chỉ trong lúc một hạt của cặp đang chạy, <strong>cả 2 hạt của cặp đó đều không có hitbox</strong>. Hạt của cặp khác đang chạy có thể đi xuyên qua chúng mà không bị tính là va chạm. Khi đứng yên, hạt có hitbox bình thường.</li><li><strong>Cặp bị chặn:</strong> trong lúc hạt của nó đang chạy (trước khi đụng), 2 hạt của cặp đó <strong>vẫn có hitbox</strong> với hạt của các cặp khác.</li><li><strong>Bóng sọc (cặp đã va chạm):</strong> khi một hạt đang chạy đụng hạt khác, cặp của hạt đang chạy bị <strong>đánh dấu</strong>: cả 2 hạt chuyển sang có <strong>sọc trắng chéo</strong>. Hạt có sọc đụng hạt khác thì <strong>không mất tim</strong> nữa. Hạt khác (chưa có sọc) đụng vào hạt có sọc thì vẫn mất tim như thường, và cặp của hạt vừa đụng bị đánh dấu. Đánh dấu giữ đến hết level (chơi lại thì xóa).</li></ul>",1)),n("h2",u,[t[9]||(t[9]=d("3.3b Cảm giác vật lý của bóng ",-1)),e(o,{type:"tip",text:"Live"}),t[10]||(t[10]=d()),t[11]||(t[11]=n("a",{class:"header-anchor",href:"#_3-3b-cam-giac-vat-ly-cua-bong","aria-label":'Permalink to "3.3b Cảm giác vật lý của bóng <Badge type="tip" text="Live" />"'},"​",-1))]),t[43]||(t[43]=h("<ul><li><strong>Khi chạy:</strong> bóng bị kéo dài nhẹ theo hướng di chuyển (dài 116%, dẹt 88%) và để lại <strong>vệt trail</strong> mờ dần (9 vị trí gần nhất).</li><li><strong>Hình dáng bóng:</strong> bóng bóng loáng (glossy) với ánh sáng từ góc trên bên trái: viền tối, thân sáng dần về phía nguồn sáng, đốm phản quang trắng, ánh phản xạ nhẹ ở đáy; mỗi bóng có <strong>bóng đổ</strong> mềm lệch xuống dưới bên phải (bóng đổ đi theo bóng khi bóng méo).</li><li><strong>Khi va chạm:</strong> cả bóng đang chạy và bóng bị đụng <strong>biến dạng đàn hồi</strong> (co giãn dao động tắt dần trong khoảng 0,7 giây, theo hướng va chạm), và <strong>cả 2 bóng bắn ra giọt nước</strong> cùng màu với chính nó (6–9 giọt mỗi bóng, vài giọt màu sáng hơn), bay ra phía ngoài chỗ chạm (hình quạt ±65°), rơi nhẹ xuống và nhỏ dần rồi biến mất (khoảng 0,3–0,5 giây). Có ở cả bản thường và bản Jelly.</li><li><strong>Khi tới bóng cùng cặp:</strong> cũng bắn giọt nước như vậy (màu của cặp): bóng vừa tới bắn ngược về phía sau, bóng kia bắn về phía trước theo hướng chạy; sau đó cặp nổ như cũ (bản Jelly: lúc hai bóng bắt đầu ép vào nhau).</li></ul>",1)),n("h2",b,[t[12]||(t[12]=d("3.3b2 Bản Jelly ",-1)),e(o,{type:"tip",text:"Live"}),t[13]||(t[13]=d()),t[14]||(t[14]=n("a",{class:"header-anchor",href:"#_3-3b2-ban-jelly","aria-label":'Permalink to "3.3b2 Bản Jelly <Badge type="tip" text="Live" />"'},"​",-1))]),t[44]||(t[44]=h('<p>Bản game phụ tại <a href="https://taigd98.github.io/dot-line/jelly/" target="_blank" rel="noreferrer"><code>/jelly/</code></a> (nút <strong>Play Jelly</strong> ở trang chủ): cùng level, cùng luật, chỉ khác cảm giác của bóng (<code>src/game/mode.ts</code>, <code>JELLY</code> trong <code>src/scenes/Game.ts</code>):</p><ul><li><strong>Khi chạy:</strong> không có trail; bóng <strong>biến dạng như thạch</strong>: kéo dài theo hướng chạy, càng nhanh càng dài (tới khoảng 1,5 lần), dẹt lại tương ứng (giữ diện tích), rung nhẹ trong lúc chạy. Độ dài đi theo một lò xo mềm nên khi bắt đầu chạy, quay đầu hay dừng lại bóng nảy qua nảy lại rồi mới tròn lại.</li><li><strong>Khi va chạm:</strong> rung mạnh và lâu hơn bản thường (biên độ 0,5 / 0,4 thay vì 0,32 / 0,22, tắt dần trong khoảng 1,3 giây thay vì 0,7 giây).</li><li><strong>Khi tới bóng cùng cặp:</strong> bóng dừng lúc chạm bóng kia, hai bóng <strong>ép vào nhau</strong> (dẹt ở chỗ chạm, 0,16 giây), <strong>nhập thành một khối</strong> (diện tích bằng tổng hai bóng, lúc đầu dài theo hướng gặp nhau rồi rung về tròn, 0,4 giây, phồng lên một chút) rồi mới <strong>nổ</strong>. Màn Well Done đến 0,5 giây sau tiếng nổ cuối.</li></ul>',2)),n("h2",p,[t[15]||(t[15]=d("3.3b3 Bản Magic ",-1)),e(o,{type:"tip",text:"Live"}),t[16]||(t[16]=d()),t[17]||(t[17]=n("a",{class:"header-anchor",href:"#_3-3b3-ban-magic","aria-label":'Permalink to "3.3b3 Bản Magic <Badge type="tip" text="Live" />"'},"​",-1))]),t[45]||(t[45]=h('<p>Bản game phụ tại <a href="https://taigd98.github.io/dot-line/magic/" target="_blank" rel="noreferrer"><code>/magic/</code></a> (nút <strong>Play Magic</strong> ở trang chủ): cùng level và luật, level là dấu niêm phong khắc trên một cánh cửa đôi (<code>src/scenes/Door.ts</code>, <code>MAGIC</code> trong <code>src/scenes/Game.ts</code>). Ảnh: <a href="./../guide/magic-assets">Magic variant: assets</a> (cửa, phía sau cửa, tia sáng, chùm sáng, hạt lấp lánh, bóng orb).</p><ul><li><p><strong>Bóng:</strong> quả cầu orb (ảnh <code>orb.png</code>) trong màu của cặp, đủ 28 màu đều có bóng đổ và điểm sáng (màu tối của orb thành màu tối hơn, màu sáng thành trắng); bóng sọc vẫn có sọc trắng.</p></li><li><p><strong>Cửa:</strong> chỉ dùng phần mặt phẳng của <code>door.png</code> (bỏ khung hoa văn hai bên; hoa văn trên và dưới nằm dưới HUD và thanh booster), đổi sang <strong>màu nền của bản thường</strong> theo theme (sáng <code>#F2EEE6</code>, tối <code>#1F2335</code>), chỉ giữ vân đá mờ của ảnh. Mặt cửa liền, <strong>không thấy khe</strong> cho tới khi bóng cuối cùng biến mất. Dây (không viền) và trang ngoài cột game như bản thường.</p></li><li><p><strong>Vào level:</strong> hai cánh cửa trượt vào từ hai bên (0,43 giây), sập lại (rung nhẹ, hạt sáng dọc khe). Sau đó hai bóng của mỗi cặp cùng nằm ở đầu thứ nhất của dây, bóng thứ hai chạy theo dây sang đầu kia (0,35–0,85 giây tùy độ dài dây), dây hiện ra phía sau nó. Trong lúc này chưa chạm được bóng. Chữ hướng dẫn (tutorial) của level, nếu có, chỉ hiện sau khi bóng chạy xong, và tắt khi người chơi làm đúng điều kiện hoặc ngay khi bóng cuối cùng biến mất. Cửa đứng yên khi pinch zoom; dây và bóng zoom như bình thường.</p></li><li><p><strong>Phá seal:</strong> gỡ hết bóng thì level trở về zoom gốc và canh giữa; trước hết <strong>map của level (mọi dây và mọi bóng ở chỗ ban đầu) hiện lại, sáng vàng như ánh sáng trong khe</strong> (0,45 giây), sau đó khe cửa mới hiện ra và ánh sáng lọt qua (0,55 giây), rồi hai cánh cửa mở ra (0,8 giây), mỗi cánh mang nửa map của nó, với chùm sáng bung ra; rồi màn <strong>Well Done</strong> hiện trên căn phòng phía sau cửa (không làm tối; căn phòng vừa khít màn hình game). Hai thanh HUD (trên, dưới) <strong>trượt ra khỏi màn hình</strong> khi cửa bắt đầu mở và <strong>trượt vào lại</strong> (thanh trên từ trên xuống, thanh dưới từ dưới lên) khi cửa đã sập cho level sau; lúc vào game lần đầu cũng vậy. <strong>CONTINUE</strong> làm cửa sập lại cho level sau; <strong>REPLAY</strong> giữ cửa đóng, bóng chạy ra lại.</p></li></ul>',2)),n("h2",v,[t[18]||(t[18]=d("3.3b4 Theme Fluffy ",-1)),e(o,{type:"tip",text:"Live"}),t[19]||(t[19]=d()),t[20]||(t[20]=n("a",{class:"header-anchor",href:"#_3-3b4-theme-fluffy","aria-label":'Permalink to "3.3b4 Theme Fluffy <Badge type="tip" text="Live" />"'},"​",-1))]),t[46]||(t[46]=h('<p>Bản game phụ tại <a href="https://taigd98.github.io/dot-line/fluffy/" target="_blank" rel="noreferrer"><code>/fluffy/</code></a> (nút <strong>Play Fluffy</strong> ở trang chủ): cùng level và luật, mỗi hạt là một <strong>cục bông lông có mặt</strong> (<code>src/scenes/fluffy.ts</code>, <code>FLUFFY</code> trong <code>src/scenes/Game.ts</code>). Ảnh gốc và quy cách: <a href="./../guide/fluffy-assets">Fluffy theme: assets</a>.</p><table tabindex="0"><thead><tr><th>Lúc</th><th>Mặt</th><th>Chuyển động / hiệu ứng</th></tr></thead><tbody><tr><td>Đứng yên</td><td>ngủ (nhắm mắt)</td><td>thở: phồng xẹp (dọc ±4,5%, ngang ±2,5%) và nhấp nhô lên xuống 7% bán kính, mỗi cục lệch nhịp</td></tr><tr><td>Đứng yên, cặp đã va chạm (bị đánh dấu)</td><td>ngủ, có sọc trắng như bản thường. <strong>Khi có ảnh <code>face-awake.png</code>:</strong> thức, mở mắt, không sọc</td><td>thở như lúc ngủ</td></tr><tr><td>Tap vào cục</td><td></td><td>11–15 túm lông bay ra mọi phía ngay chỗ tap</td></tr><tr><td>Tap vào khoảng trống</td><td></td><td>5–7 cục lông tí hon (đủ 4 biểu cảm, màu các cặp trong level, rất mờ) văng lên, xoay rồi rơi xuống và mờ dần</td></tr><tr><td>Đang chạy</td><td>mắt tròn, ngạc nhiên</td><td>to hơn 6%, nảy nhanh; <strong>trail dài</strong> (24 khung hình) màu của cục, rắc <strong>sparkle</strong> lấp lánh (sao 4 cánh trắng và màu của cục, xoay và nhỏ dần)</td></tr><tr><td>Va chạm (cả hai cục)</td><td><code>&gt; &lt;</code> (0,6 giây, và suốt lúc bị bật về)</td><td>bẹp rồi nảy; 10–14 túm lông <strong>đúng một màu, màu của cục đó</strong>, bay ra phía ngoài chỗ chạm, trôi nhẹ rồi mờ dần</td></tr><tr><td>Tới bóng cùng cặp</td><td><code>^ ^</code> vui</td><td>dừng lúc chạm nhau: 14–18 túm lông bay ra mọi phía chỗ hai cục chạm, hai cục <strong>va như hai cục va chạm</strong> (bật ra một chút rồi về, bẹp và rung) và đứng cạnh nhau <strong>0,2 giây</strong> (<code>HUG_HOLD</code> trong <code>src/game/tuning.ts</code>; chỉnh bằng thanh <em>Pair touch → hearts</em> trong cheat ⚙ tuning của bản Fluffy, bấm Confirm khi chạy local để ghi vào code); rồi 6–9 trái tim nhỏ <strong>cùng màu với cặp</strong> bay lên, cùng lúc hai cục phồng nhẹ rồi thu nhỏ hết trong 0,2 giây</td></tr></tbody></table><ul><li><strong>Nền:</strong> ô pattern các mặt cục lông (4 biểu cảm, xếp chéo), tương phản thấp, thưa và nhỏ (các mặt nhỏ, cách nhau xa, nhạt gần như màu nền), mỗi theme một ô (kem / xanh đậm). Nền nằm trong board nên <strong>zoom cùng board</strong>, mỗi ô phủ 1024 px của board, và <strong>cuộn chậm theo đường chéo</strong> từ trên trái xuống dưới phải (22 px/giây).</li><li><strong>Tutorial:</strong> bàn tay 👆 như bản thường. <strong>Khi có ảnh <code>hand.png</code>:</strong> thay bằng bàn chân lông xù, đầu ngón đặt đúng vào cục.</li><li><strong>Màu:</strong> thân xám của cục lông (lông mờ, không bóng, sợi lông rõ, đánh sáng từ trên trái nên thấy khối tròn; hướng đèn và độ sáng tối chỉnh bằng nhóm <em>Ball light</em> trong cheat ⚙ tuning: hướng đèn, độ cao đèn, độ sáng phía tối, độ sáng phía được chiếu, độ sáng mềm chỗ chiếu mạnh nhất; <code>LIGHT_*</code> trong <code>src/game/tuning.ts</code>) được tô theo 28 màu như bóng orb; cục bị đánh dấu (đã va chạm) có sọc trắng (khi có ảnh mặt thức thì bỏ sọc, thay bằng mặt thức).</li><li>Màn Well Done đến 1 giây sau khi cặp cuối biến mất (với <code>HUG_HOLD</code> 0,2: 1,2 giây sau khi chạm nhau).</li></ul>',3)),n("h2",y,[t[21]||(t[21]=d("3.3c Giao diện sáng / tối ",-1)),e(o,{type:"tip",text:"Live"}),t[22]||(t[22]=d()),t[23]||(t[23]=n("a",{class:"header-anchor",href:"#_3-3c-giao-dien-sang-toi","aria-label":'Permalink to "3.3c Giao diện sáng / tối <Badge type="tip" text="Live" />"'},"​",-1))]),t[47]||(t[47]=h('<p>Bật trong <strong>Settings</strong> (nút Pause ở góc trên trái mở Settings, game tạm dừng; nút <strong>THEME: LIGHT/DARK</strong>, ghi nhớ trong trình duyệt, mặc định sáng).</p><table tabindex="0"><thead><tr><th></th><th>Sáng</th><th>Tối</th></tr></thead><tbody><tr><td>Nền</td><td><code>#fbfaf3</code> (kem)</td><td><code>#171a24</code> (xanh đen)</td></tr><tr><td>Bóng đổ của bóng</td><td>nâu nhạt, mờ</td><td>đen, đậm hơn</td></tr><tr><td>Thanh tiến độ (nền)</td><td><code>#e5e2da</code></td><td><code>#2c3142</code></td></tr><tr><td>Chữ hướng dẫn</td><td>nâu <code>#8a5a2b</code></td><td>cam nhạt <code>#f3c98b</code></td></tr><tr><td>Màu &quot;black&quot; của bảng màu</td><td><code>#494E68</code></td><td>sáng hơn <code>#7B83AA</code> để không chìm vào nền</td></tr></tbody></table>',2)),n("h2",k,[t[24]||(t[24]=d("3.4 Cặp biến mất ",-1)),e(o,{type:"tip",text:"Live"}),t[25]||(t[25]=d()),t[26]||(t[26]=n("a",{class:"header-anchor",href:"#_3-4-cap-bien-mat","aria-label":'Permalink to "3.4 Cặp biến mất <Badge type="tip" text="Live" />"'},"​",-1))]),t[48]||(t[48]=n("ul",null,[n("li",null,"Khi hạt di chuyển chạm vào hạt đích → cả 2 hạt vỡ ra, có effect văng màu tại chỗ chạm, rồi biến mất."),n("li",null,[n("strong",null,"Sợi dây cũng biến mất hoàn toàn"),d(" khỏi board. Chỉ khi dọn xong mọi cặp, tất cả các dây mới hiện lại (mờ dần trong khoảng 0,7 giây) bằng màu Completed "),n("code",null,"#6977C2"),d(", ghép thành hình vẽ của level, rồi màn thắng mới hiện.")]),n("li",null,[n("strong",null,"Hạt càng to, effect vỡ càng to.")])],-1)),n("h2",_,[t[27]||(t[27]=d("3.5 Thắng và thua ",-1)),e(o,{type:"tip",text:"Live"}),t[28]||(t[28]=d()),t[29]||(t[29]=n("a",{class:"header-anchor",href:"#_3-5-thang-va-thua","aria-label":'Permalink to "3.5 Thắng và thua <Badge type="tip" text="Live" />"'},"​",-1))]),t[49]||(t[49]=h("<ul><li><strong>Thắng:</strong> mọi cặp trên board đã biến mất → confetti và màn &quot;Well Done!&quot; (board để trống, không hiện lại hình vẽ phía sau).</li><li><strong>Kết thúc level:</strong> bóng cuối chạy với tốc độ bình thường; khi nổ, màn &quot;Well Done!&quot; hiện sau khoảng 0,5 giây (không còn slow motion hay zoom).</li><li><strong>Kéo màn:</strong> kéo được ở mọi mức zoom, kể cả nhỏ nhất.</li><li><strong>Thua:</strong> mỗi lần va chạm mất 1 tim, mỗi level có 3 tim. Hết tim = thua màn. Màn &quot;Out of Hearts!&quot; có 2 nút: <strong>PLAY ON</strong> (xanh, nhãn AD, xem quảng cáo; chưa nối quảng cáo thật): hồi đủ 3 tim và chơi tiếp đúng từ chỗ đang dở (các cặp đã dọn vẫn mất, cặp đã sọc vẫn sọc); <strong>QUIT</strong> (xám): mở pop-up <strong>&quot;Are you sure?&quot;</strong> cho thấy tiến độ level (&quot;You have cleared X of Y lines.&quot;, thanh tiến độ và %) kèm cảnh báo &quot;If you replay now, you will lose your progress on this level.&quot;, với 2 nút <strong>PLAY ON</strong> (xanh, AD, như trên) và <strong>REPLAY</strong> (đỏ: chơi lại level từ đầu). Màn thắng &quot;Well Done!&quot; (confetti, nút CONTINUE) và màn thua &quot;Out of Hearts!&quot; (nút RETRY) vẽ trong Phaser theo phong cách của skill <code>prototype-ui</code> (font Lilita One, tiêu đề gradient).</li></ul>",1)),n("h2",F,[t[30]||(t[30]=d("3.6 HUD và nút (theo clip) ",-1)),e(o,{type:"tip",text:"Live"}),t[31]||(t[31]=d()),t[32]||(t[32]=n("a",{class:"header-anchor",href:"#_3-6-hud-va-nut-theo-clip","aria-label":'Permalink to "3.6 HUD và nút (theo clip) <Badge type="tip" text="Live" />"'},"​",-1))]),t[50]||(t[50]=h('<table tabindex="0"><thead><tr><th>Vị trí</th><th>Thành phần</th></tr></thead><tbody><tr><td>Trên cùng, bên trái</td><td>Nút Pause: mở Settings (tạm dừng game, chọn giao diện sáng/tối, RESUME)</td></tr><tr><td>Trên cùng, ở giữa</td><td>3 trái tim (mạng)</td></tr><tr><td>Dưới HUD</td><td>Thanh tiến độ: % cặp đã dọn trong level</td></tr><tr><td>Panel dưới cùng</td><td>Dải booster, cùng màu nền với board và nằm đè lên vùng chơi (board trượt xuống dưới nó khi zoom/kéo), góc trên bo tròn, bóng đổ nhẹ. Dải trên cùng (HUD) cũng có nền như vậy. Chạm vào 2 dải này không tính là chạm vào board.</td></tr><tr><td>Booster Hint</td><td>Nút bóng đèn, nhãn AD (xem quảng cáo để dùng). Khi bấm: chọn ngẫu nhiên một hạt đang tap được (có đường thông), camera zoom vào hạt đó tới 1.5 lần so với bình thường, rồi hạt chạy nhấp nhả một đoạn ngắn dọc theo dây để thu hút sự chú ý của người chơi.</td></tr><tr><td>Booster Cut (cây kéo)</td><td>Nút cây kéo, nhãn AD. Bấm để cầm kéo (nút sáng viền vàng và nhấp nháy, dòng &quot;Tap a line to cut it&quot; hiện phía trên panel); chạm vào một dây hoặc hạt của cặp đang đứng yên thì cặp đó bị cắt: nổ ở chỗ cắt và ở 2 hạt, cặp biến mất và tính là đã dọn. Chạm trượt thì vẫn cầm kéo; bấm lại nút để bỏ. Cắt cặp cuối cùng thì thắng màn như thường.</td></tr></tbody></table>',1)),n("h2",T,[t[33]||(t[33]=d("3.7 Bảng màu ",-1)),e(o,{type:"tip",text:"Live"}),t[34]||(t[34]=d()),t[35]||(t[35]=n("a",{class:"header-anchor",href:"#_3-7-bang-mau","aria-label":'Permalink to "3.7 Bảng màu <Badge type="tip" text="Live" />"'},"​",-1))]),t[51]||(t[51]=h('<p>Nguồn: vật liệu <code>Voxel_*</code> của game Cube Blast (file <code>VoxelMaterials.json</code>). Mỗi màu có <strong>Base</strong> (<code>_BaseColor</code>: màu bóng và dây) và dải sáng tối <code>_RampKey</code>: <strong>Dark</strong> (nấc tối nhất: viền bóng), <strong>Lit</strong> (nấc gần 0,6: phần sáng của thân bóng) và <strong>Light</strong> (nấc sáng nhất: đốm sáng). White và Black không dùng vì bị chìm vào nền; level cũ có màu không còn trong bảng được đổi màu khi mở.</p><table tabindex="0"><thead><tr><th>Tên</th><th>Base</th><th>Dark</th><th>Lit</th><th>Light</th></tr></thead><tbody><tr><td>blue</td><td><code>#1020EB</code></td><td><code>#270B73</code></td><td><code>#765DFF</code></td><td><code>#AC9BFF</code></td></tr><tr><td>brown</td><td><code>#93592F</code></td><td><code>#5B2600</code></td><td><code>#8E4E2C</code></td><td><code>#E7A379</code></td></tr><tr><td>cyan</td><td><code>#2AC5F2</code></td><td><code>#1575BE</code></td><td><code>#2DD1FF</code></td><td><code>#DAF7FF</code></td></tr><tr><td>dark_blue</td><td><code>#0C3E7D</code></td><td><code>#042857</code></td><td><code>#1E65BE</code></td><td><code>#69ABFF</code></td></tr><tr><td>dark_green</td><td><code>#0A4414</code></td><td><code>#003508</code></td><td><code>#0C821F</code></td><td><code>#34B94A</code></td></tr><tr><td>green</td><td><code>#109616</code></td><td><code>#006314</code></td><td><code>#1FA125</code></td><td><code>#3EDE45</code></td></tr><tr><td>lavender</td><td><code>#B671F3</code></td><td><code>#6F18B9</code></td><td><code>#DF99FF</code></td><td><code>#ECD5FF</code></td></tr><tr><td>light_green</td><td><code>#B4F484</code></td><td><code>#357109</code></td><td><code>#9FF85F</code></td><td><code>#C3FF96</code></td></tr><tr><td>light_orange</td><td><code>#FFA461</code></td><td><code>#E26C2E</code></td><td><code>#FFB88D</code></td><td><code>#FFD1B1</code></td></tr><tr><td>light_pink</td><td><code>#FF97AF</code></td><td><code>#B02E4C</code></td><td><code>#FFB3A7</code></td><td><code>#FFF5F2</code></td></tr><tr><td>light_yellow</td><td><code>#FDE372</code></td><td><code>#A89314</code></td><td><code>#EDE12C</code></td><td><code>#FFFDC6</code></td></tr><tr><td>lime</td><td><code>#60E414</code></td><td><code>#2B6F00</code></td><td><code>#50EE1C</code></td><td><code>#ACF79B</code></td></tr><tr><td>magenta</td><td><code>#F00DE7</code></td><td><code>#B20398</code></td><td><code>#FF36F7</code></td><td><code>#FFB3F6</code></td></tr><tr><td>maroon</td><td><code>#73080A</code></td><td><code>#4B0002</code></td><td><code>#891518</code></td><td><code>#D44548</code></td></tr><tr><td>navy</td><td><code>#0C1465</code></td><td><code>#001276</code></td><td><code>#197DFF</code></td><td><code>#C4EFFF</code></td></tr><tr><td>olive</td><td><code>#936908</code></td><td><code>#6C4D00</code></td><td><code>#C8A930</code></td><td><code>#FFE99E</code></td></tr><tr><td>olive_green</td><td><code>#63A729</code></td><td><code>#2B3C00</code></td><td><code>#6EA814</code></td><td><code>#C0EE98</code></td></tr><tr><td>orange</td><td><code>#EC8C0F</code></td><td><code>#C88F25</code></td><td><code>#FFD896</code></td><td><code>#FFF0C9</code></td></tr><tr><td>orange_red</td><td><code>#F35021</code></td><td><code>#B04009</code></td><td><code>#FF9B14</code></td><td><code>#FFF0A2</code></td></tr><tr><td>pink</td><td><code>#FC547B</code></td><td><code>#892655</code></td><td><code>#FFA5C9</code></td><td><code>#FFEDF4</code></td></tr><tr><td>purple</td><td><code>#820EE8</code></td><td><code>#450080</code></td><td><code>#811ED4</code></td><td><code>#E094FF</code></td></tr><tr><td>red</td><td><code>#E5171B</code></td><td><code>#840005</code></td><td><code>#FF4063</code></td><td><code>#FF8F95</code></td></tr><tr><td>sky_blue</td><td><code>#0E6FE8</code></td><td><code>#0036B9</code></td><td><code>#008BFF</code></td><td><code>#AEE2FF</code></td></tr><tr><td>spring_green</td><td><code>#17E482</code></td><td><code>#006F4A</code></td><td><code>#69FFB8</code></td><td><code>#CBFFE7</code></td></tr><tr><td>teal</td><td><code>#04778E</code></td><td><code>#004F5E</code></td><td><code>#10A2C3</code></td><td><code>#86F1FF</code></td></tr><tr><td>turquoise</td><td><code>#13EDDB</code></td><td><code>#01707B</code></td><td><code>#00FFF2</code></td><td><code>#94FFF8</code></td></tr><tr><td>yellow</td><td><code>#FDD201</code></td><td><code>#E98E3F</code></td><td><code>#FFED3D</code></td><td><code>#FFF9BF</code></td></tr><tr><td>yellow_green</td><td><code>#A3F408</code></td><td><code>#527D00</code></td><td><code>#C8F72D</code></td><td><code>#E8FF70</code></td></tr></tbody></table><p><strong>Nền:</strong> theme sáng <code>#F2EEE6</code>, theme tối <code>#1F2335</code>. Dây chỉ có màu của nó, <strong>không có viền</strong>.</p><p><strong>Màu dùng cho mỗi theme</strong> (chọn bằng mắt; <code>THEME_COLOURS</code> trong <code>src/core/palette.ts</code>):</p><table tabindex="0"><thead><tr><th>Theme</th><th>Màu giữ nguyên</th><th>Màu khó nhìn, sẽ được đổi</th></tr></thead><tbody><tr><td>Sáng (17 màu)</td><td>blue, brown, cyan, green, lavender, light_orange, light_pink, lime, magenta, olive_green, orange, orange_red, pink, purple, red, sky_blue, spring_green</td><td>dark_blue, dark_green, light_green, light_yellow, maroon, navy, olive, teal, turquoise, yellow, yellow_green</td></tr><tr><td>Tối (19 màu)</td><td>cyan, green, lavender, light_green, light_orange, light_pink, light_yellow, lime, magenta, olive_green, orange, orange_red, pink, red, sky_blue, spring_green, turquoise, yellow, yellow_green</td><td>blue, brown, dark_blue, dark_green, maroon, navy, olive, purple, teal</td></tr></tbody></table><p><strong>Cách đổi khi chơi</strong> (<code>themeColours</code> trong <code>src/core/palette.ts</code>, gọi từ <code>recolour</code> trong <code>src/scenes/Game.ts</code>):</p><ol><li>Chỉ đổi màu <strong>không nằm trong danh sách giữ</strong> của theme đang bật. Màu trong danh sách giữ không bao giờ bị đổi.</li><li>Màu thay là một màu trong danh sách giữ, <strong>không cần cùng tông</strong> với màu gốc. Điều kiện: không trùng màu, không cùng nhóm tông, và khác rõ (độ khác màu ≥ 25) với <strong>mọi dây đè lên hoặc chạy gần nó</strong> (cách nhau dưới 60 px, như <code>nearPairs</code> của generator), tính theo màu đang hiện của các dây đó.</li><li>Trong các màu thỏa điều kiện: ưu tiên màu gần giống màu gốc nhất, rồi màu đang ít dùng trong level. Dây có nhiều dây gần được chọn trước; sau đó chọn lại vài lượt để dây chọn sớm cũng tính tới các dây chọn sau.</li><li>Nếu không còn màu nào thỏa (level quá dày, mọi màu giữ đều đụng một dây gần), lấy màu đụng ít dây nhất. Với 30 level đang chơi: còn 13 chỗ ở theme sáng (theme sáng không còn màu nào của nhóm vàng, nên các màu vàng thường thành cam và dễ đụng orange_red; vd. Butterfly, Christmas bear, các level Dancer, Glass poppy, Ice cream cone) và 1 chỗ ở theme tối (Dancer parasol).</li></ol><p>Vì màu thay tùy theo các dây xung quanh, cùng một màu gốc có thể thành các màu khác nhau ở các level khác nhau. Đổi theme thì chọn lại theo theme mới. File level vẫn giữ màu gốc (editor không đổi). Generator và phần kiểm tra của editor không biết level xung quanh, nên vẫn ước lượng mỗi màu khó nhìn thành màu giữ gần nhất cùng tông (<code>shownColour</code>).</p><p><strong>Nhóm tông màu:</strong> 28 màu chia thành 10 nhóm cùng tông (sáng hay đậm đều tính là cùng tông; <code>FAMILIES</code> trong <code>src/core/palette.ts</code>):</p><table tabindex="0"><thead><tr><th>Nhóm</th><th>Màu</th></tr></thead><tbody><tr><td>Đỏ</td><td>red, maroon</td></tr><tr><td>Cam</td><td>orange_red, orange, light_orange, brown</td></tr><tr><td>Vàng</td><td>yellow, light_yellow, olive</td></tr><tr><td>Xanh cốm</td><td>lime, yellow_green, light_green, olive_green</td></tr><tr><td>Xanh lá</td><td>green, dark_green, spring_green</td></tr><tr><td>Xanh ngọc</td><td>turquoise, cyan, teal</td></tr><tr><td>Xanh dương</td><td>blue, sky_blue, dark_blue, navy</td></tr><tr><td>Tím</td><td>purple, lavender</td></tr><tr><td>Hồng tím</td><td>magenta</td></tr><tr><td>Hồng</td><td>pink, light_pink</td></tr></tbody></table><p><strong>Phối màu trong một level</strong> (<code>colourPairs</code> trong <code>src/core/generator.ts</code>):</p><ul><li><strong>Cấm tuyệt đối:</strong> hai dây gần nhau (chạm, cắt hoặc cách nhau dưới <strong>60 px</strong>) có màu <strong>giống nhau</strong>: cùng màu, cùng tông, hoặc khác tông nhưng <strong>nhìn giống nhau trên màn hình</strong> (ví dụ spring_green cạnh turquoise, green cạnh olive_green, blue cạnh purple). &quot;Nhìn giống&quot; đo bằng độ khác biệt màu theo mắt người (CIEDE2000, phải ≥ 25) trên đúng màu người chơi thấy, ở <strong>cả theme sáng và theme tối</strong> (sau khi đổi màu theo theme). Level checks báo lỗi (warn) nếu có, và <code>publish:levels</code> không cho đưa level đó lên (<code>farApart</code> trong <code>src/core/palette.ts</code>).</li><li><strong>Càng nhiều màu càng tốt:</strong> mỗi màu được dùng một lần trước khi màu nào dùng lần hai (level từ 28 cặp trở lên dùng đủ 28 màu), và trong số đó nhóm tông ít dùng nhất được chọn trước, để hạn chế tối đa các dây cùng tông trong cả level.</li><li>Cách làm: tô dây khó nhất trước (dây còn ít màu hợp lệ nhất), thử tối đa 60 cách xáo trộn, giữ cách không vi phạm và dùng màu đều nhất. Dây chéo X/T (bước 2 của editor) cũng chọn màu theo cùng quy tắc. Ô <strong>Colours</strong> của editor là số màu tối đa (mặc định 28).</li><li>Khi game đổi màu theo theme (bảng trên), màu chỉ được đổi <strong>trong cùng nhóm tông</strong> và <strong>luôn đổi sang cùng một màu</strong> (không phụ thuộc level), nên generator biết chính xác màu người chơi sẽ thấy và giữ quy tắc trên ở cả hai theme. Vì nhiều màu nhạt chìm trên nền sáng và nhiều màu đậm chìm trên nền tối, một level 28 màu khi chơi hiện khoảng 18 màu ở theme sáng và 19 màu ở theme tối.</li></ul>',12)),n("h2",x,[t[36]||(t[36]=d("3.8 Level ",-1)),e(o,{type:"tip",text:"Live"}),t[37]||(t[37]=d()),t[38]||(t[38]=n("a",{class:"header-anchor",href:"#_3-8-level","aria-label":'Permalink to "3.8 Level <Badge type="tip" text="Live" />"'},"​",-1))]),t[52]||(t[52]=h('<ul><li>Mỗi level là một hình vẽ ghép từ các cặp hạt và dây (ví dụ cái micro trong clip).</li><li><strong>Bộ level đang chơi (Play order, <code>levels/game.json</code>):</strong> 30 level của <strong>chapter 6</strong>, gen lại từ hình gốc của bộ cũ (2 level hướng dẫn của chapter 1 + 28 level tranh line art của chapter 5) bằng generator hiện tại (<code>npm run levels:chapter6</code>). LEVEL 1 hướng dẫn bấm, LEVEL 2 hướng dẫn va chạm, LEVEL 3 hướng dẫn pinch zoom. Bản build của game chứa đúng các level này.</li><li>Bộ cũ vẫn còn trong repo nhưng không chơi: hệ thống 100 level (chapter 1, xem <a href="./../guide/level-system">Level system</a> và <code>design/level-system.xlsx</code>), 10 level mở đầu cũ (bộ &quot;Intro&quot;), chapter 5 bản trước.</li><li><strong>Hướng dẫn:</strong> level có trường <code>tutorial</code> hiện bàn tay chỉ vào hạt và dòng chữ (Tap a dot to send it home / Blocked dots bounce back / Pinch to zoom); biến mất sau lần bấm hoặc zoom đầu tiên. Ở level hướng dẫn va chạm (<code>collision</code>), <strong>lần đụng đầu tiên không mất tim</strong>, rồi hiện thông báo &quot;Free this time! Next bump costs a heart&quot;.</li><li><strong>Nhãn &quot;Hard&quot;</strong> hiện trên tim ở các level vị trí khó của hệ thống level (<code>category: &quot;hard&quot;</code>); level không thuộc hệ thống thì hiện khi độ khó từ 4 trở lên.</li><li>Số cặp mỗi level, số màu, cách tăng độ khó qua các level: <em>TBD</em>.</li><li>Điều kiện để level giải được: luôn tồn tại một thứ tự gỡ dọn sạch được board. Cách kiểm tra (bằng tay hay bằng công cụ): <em>TBD</em>.</li></ul>',1))])}const q=c(a,[["render",E]]);export{L as __pageData,q as default};
